contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] calldata ndcs) public {
        uint256 n = ndcs.length;
        for (uint256 i = 0; i < n; ++i) {
            require(ndcs[i] != address(0));
        }

        uint256 beforeLen = c.getNodeDelegatorQueue().length;
        uint256 max = c.maxNodeDelegatorCount();

        bool reverted;
        try c.addNodeDelegatorContractToQueue(ndcs) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address[] memory queue = c.getNodeDelegatorQueue();
        bool ok;
        if (reverted) {
            ok = (beforeLen + n > max);
        } else {
            ok = (queue.length == beforeLen + n) && (queue.length <= max);
            if (ok) {
                for (uint256 i = 0; i < n; ++i) {
                    if (queue[beforeLen + i] != ndcs[i]) {
                        ok = false;
                        break;
                    }
                }
            }
        }

        assert(ok);
    }
}

