contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a1, address a2, uint256 newMax) public {
        require(a1 != address(0) && a2 != address(0));
        require(newMax >= 2 && newMax < 5);
        c.updateMaxNodeDelegatorCount(newMax);
        address[] memory batch1 = new address[](1);
        batch1[0] = a1;
        c.addNodeDelegatorContractToQueue(batch1);
        address[] memory q = c.getNodeDelegatorQueue();
        uint256 lenAfterFirst = q.length;
        address[] memory batch2 = new address[](2);
        batch2[0] = a2;
        batch2[1] = a1;
        bool reverted;
        // top-level change calls must not be nested in try; do a plain call guarded by a view precheck
        // current length is 1, adding 2 exceeds newMax (>=2, <5) only when newMax < 3
        if (c.maxNodeDelegatorCount() < lenAfterFirst + 2) {
            address[] memory b = new address[](2);
            b[0] = a2;
            b[1] = a1;
            try c.addNodeDelegatorContractToQueue(b) { reverted = false; }
            catch { reverted = true; }
        } else {
            c.addNodeDelegatorContractToQueue(batch2);
            reverted = false;
        }
        address[] memory qAfter = c.getNodeDelegatorQueue();
        assert(
            (reverted && qAfter.length == lenAfterFirst && qAfter.length == 1 && qAfter[0] == a1)
            ||
            (!reverted && qAfter.length == 3 && qAfter[0] == a1 && qAfter[1] == a2 && qAfter[2] == a1)
        );
    }
    receive() external payable {}
}

